+/// The attribute names `@types/react` at `file` declares for `element`, `key` aside: every one when `full`, else the
+/// curated subset (`react_types::is_curated_html_attr`); empty without React's types. Cached per run; records the
+/// augmentations it reads either way.
+fn element_attribute_names(element: &str, file: &Utf8Path, full: bool, ctx: &ResolutionContext) -> Arc<[String]> {
+    let key = format!("{file}\0{element}\0{full}");
+    note_augmentations(file, ctx);
+    if let Some(names) = ctx.attribute_names.get(&key) {
+        return names.clone();
+    }
+    let declared = react_attribute_names(element, file, ctx).into_iter();
+    let names: Arc<[String]> = if full {
+        declared.filter(|name| name != "key").collect()
+    } else {
+        declared.filter(|name| crate::react_types::is_curated_html_attr(element, name)).collect()
+    };
+    ctx.attribute_names.insert(key, names.clone());
+    names
